-- Autoevaluación dentro de la entrega (2026-11-16)
-- Cada clase tiene sus preguntas de autoevaluación (antes solo estaban dentro del PDF). La alumna las responde (Sí / A veces / No) al entregar el trabajo;
-- la profesora ve las respuestas en "Corregir". No se califican. Si la clase no tiene autoevaluación, no se pide nada.
alter table public.lecciones add column if not exists autoevaluacion jsonb;      -- ["¿Pregunta?", ...]  (null o [] = sin autoevaluación)
alter table public.entregas add column if not exists autoevaluacion jsonb;       -- [{"q":"¿Pregunta?","r":"si|a_veces|no"}, ...]

grant insert (autoevaluacion) on public.entregas to authenticated;   -- la alumna inserta por columnas permitidas

create or replace function public._entrega_autoeval() returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
declare pre jsonb; r jsonb := '[]'::jsonb; n int; i int; v text; resp jsonb := coalesce(new.autoevaluacion, 'null'::jsonb);
begin
  if public.es_admin() then return new; end if;
  select l.autoevaluacion into pre from public.lecciones l where l.id = new.leccion_id;
  if new.leccion_id is null or pre is null or jsonb_typeof(pre) <> 'array' or jsonb_array_length(pre) = 0 then new.autoevaluacion := null; return new; end if;
  n := jsonb_array_length(pre);
  if jsonb_typeof(resp) <> 'array' or jsonb_array_length(resp) <> n then raise exception 'FALTA_AUTOEVALUACION' using errcode = 'P0001'; end if;
  for i in 0 .. n - 1 loop
    v := resp -> i ->> 'r';
    if v is null or v not in ('si', 'a_veces', 'no') then raise exception 'FALTA_AUTOEVALUACION' using errcode = 'P0001'; end if;
    r := r || jsonb_build_array(jsonb_build_object('q', pre ->> i, 'r', v));   -- la pregunta se toma de la clase (no del cliente)
  end loop;
  new.autoevaluacion := r;
  return new;
end $$;
drop trigger if exists entrega_autoeval on public.entregas;
create trigger entrega_autoeval before insert on public.entregas for each row execute function public._entrega_autoeval();

